export function authoredFrame(context,{id}){const host=el('div',{'data-authored-session':''}),authoredMemory=new Map(),authoredMemoryDirty=new Set();let retainedDraft=null,current;function mount(){current?.abort();if(context.signal.aborted)return;current=new AbortController();const signal=anySignal([context.signal,current.signal]);host.replaceChildren(authoredSession({...context,signal,retryAuthored:mount,authoredMemory,authoredMemoryDirty,retainDraft:value=>retainedDraft=value},{id}));if(retainedDraft){const details=el('details',{'data-retained-exam-answers':''},el('summary',{},document.documentElement.lang.startsWith('uz')?'Saqlangan mahalliy javoblar':'Retained local answers'));for(const [key,raw]of Object.entries(retainedDraft)){if(!key.startsWith('la_listening_test_'))continue;try{for(const field of ['answers','reviewAnswers'])for(const [q,answer]of Object.entries(JSON.parse(raw)[field]||{}))if(/^([1-9]|[1-3][0-9]|40)$/.test(q)&&typeof answer==='string')details.append(el('p',{},(field==='reviewAnswers'?'Review Q':'Q')+q+': '+answer));}catch{}}host.prepend(details);}}context.signal.addEventListener('abort',()=>{retainedDraft=null;authoredMemory.clear();authoredMemoryDirty.clear();current?.abort();},{once:true});mount();return host;}
